import{_ as l,a0 as i,w as s,s as a,I as n,x as t,a1 as p,A as r,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"米科·哈普宁：开源软件将使世界更安全 | LCTT x X-CMD","titleTemplate":false,"description":"米科·哈普宁：开源软件将使世界更安全 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"米科·哈普宁：开源软件将使世界更安全 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"米科·哈普宁：开源软件将使世界更安全 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Mikko Hypponen--Open Source Software Will Make the World More Secure","title":"米科·哈普宁：开源软件将使世界更安全","tag":"201311","desc":""},"relativePath":"201311/Mikko Hypponen--Open Source Software Will Make the World More Secure.md","filePath":"[post].md"}'),d={name:"201311/Mikko Hypponen--Open Source Software Will Make the World More Secure.md"};function m(f,e,k,w,T,x){const o=i("Link");return s(),a("div",null,[e[14]||(e[14]=n("h1",{id:"米科·哈普宁-开源软件将使世界更安全",tabindex:"-1"},[t("米科·哈普宁：开源软件将使世界更安全 "),n("a",{class:"header-anchor",href:"#米科·哈普宁-开源软件将使世界更安全","aria-label":"Permalink to “米科·哈普宁：开源软件将使世界更安全”"},"​")],-1)),n("p",null,[e[1]||(e[1]=t("安全专家米科·哈普宁(Mikko Hypponen)于上周在爱丁堡举行的",-1)),p(o,{href:"http://events.linuxfoundation.org/events/linuxcon-europe"},{default:r(()=>[...e[0]||(e[0]=[t("LinuxCon and CloudOpen Europe",-1)])]),_:1}),e[2]||(e[2]=t("会议上的主题演讲中说：“开源软件可以作为一个方法来打击全球监视无辜居民的行为。”",-1))]),e[15]||(e[15]=u('<p><img src="http://www.linux.com/images/stories/41373/Mikko-Hypponen-3.jpg" alt=""></p><p><em>米科·哈普宁，芬兰F-Secure的首席研究员，在爱丁堡举行的LinuxCon and CloudOpen Europe 2013会议上讲话。</em></p><p>计算和全球网络增加的进步使得存储和传输数据变得便宜且简单。哈普宁说这创造了无比的连通性、进步和创新，但是同样使得大规模的数据被访问到就像NSA的棱镜项目揭示的那样，这事件随着前美国政府员工爱德华·斯诺登(Edward Snowden)泄漏的一系列顶级机密文件而公开。</p><p>哈普宁，芬兰F-Secure的首席研究员说：“前几年我们已经意识到数据是廉价的。我们永远不必再删除任何数据。这促成了很多伟大的事情，但同样也引发了大规模地毯式的监视。”</p><p>哈普宁说：“这些监视会访问我们的个人数据，包括电话记录、地理位置、电子邮件和搜索引擎请求，有些可能是被授权的。”</p><p>他说：“我相信一些监控是好的。如果有一项研究来找出校园枪击者或者毒枭或者恐怖组织成员等等，我们应该已经有技术手段这么做，但是我们首先必须持有怀疑。”</p><p>哈普宁说：“但是收集通信和每个人的个人数据不仅是对隐私的侵犯，还是对民主的威胁。”</p><p>他说：“即使你如今对政府的行为认可，但是我们不知道政府会在今后的20年怎么样。如果他们有你20年的搜索数据，他们会找出一些非法的或者令人尴尬的理由来扭曲你的手。”</p><p>哈普宁说：“虽然泄漏事件使得一些IT专家质疑他们的数据存储的安全性和经由美国服务商的的路由，但绕开这些公司和服务不能解决问题。同样不能每个国家都花费和金钱来建造他们自己的替代品。”</p><p>哈普宁说：“要跨越国际边际地工作，开发者应该团结起来建造一个安全和可靠的软件和服务来防止后门篡改和用户隐私。”</p><p>他说：“我建议开源软件对这个问题提供一个解决方案。那么国家就不必独自做这件事。这将会变得安全、开放和免费。”</p><hr>',12)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),p(o,{href:"http://www.linux.com/news/featured-blogs/200-libby-clark/745585-mikko-hypponen-open-source-software-will-make-the-world-more-secure"},{default:r(()=>[...e[3]||(e[3]=[t("http://www.linux.com/news/featured-blogs/200-libby-clark/745585-mikko-hypponen-open-source-software-will-make-the-world-more-secure",-1)])]),_:1})]),n("p",null,[e[7]||(e[7]=t("译者：",-1)),p(o,{href:"https://github.com/geekpi"},{default:r(()=>[...e[5]||(e[5]=[t("geekpi",-1)])]),_:1}),e[8]||(e[8]=t(" 校对：",-1)),p(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=t("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原创翻译，",-1)),p(o,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[t("Linux中国",-1)])]),_:1}),e[13]||(e[13]=t(" 荣誉推出",-1))])])}const g=l(d,[["render",m]]);export{M as __pageData,g as default};
